const history = (($items('Get Enrollment History', 0, 0)[0]?.json?.records) || []).sort((a, b) => String(a.fields?.month || '').localeCompare(String(b.fields?.month || '')));
const children = ($items('Get Current Children', 0, 0)[0]?.json?.records) || [];
const waitlistEntries = ($items('Get Waitlist', 0, 0)[0]?.json?.entries) || [];
const assumptions = ($items('Get Forecast Assumptions', 0, 0)[0]?.json) || {};
const roomRatios = ($items('Get Room Ratios', 0, 0)[0]?.json?.records) || [];

const active = children.filter(c => String(c.fields?.status || '').toLowerCase() !== 'inactive');
const openWaitlist = waitlistEntries.filter(w => ['new', 'contacted', 'tour_scheduled', 'offered'].includes(String(w.fields?.status || '').toLowerCase()));

let message = `📈 *Monthly Enrollment Report*\n`;
message += `Date: ${new Date().toISOString().split('T')[0]}\n\n`;
message += `*Current Status:*\n`;
message += `Active enrollment: ${active.length} children\n`;
message += `Waitlist (open): ${openWaitlist.length} families\n\n`;

const last6 = history.slice(-6);
message += `*6-Month Trend:*\n`;
for (const h of last6) {
  const f = h.fields || {};
  const enrolled = Number(f.total_enrolled || 0);
  const rev = Number(f.monthly_revenue || 0);
  const bar = '█'.repeat(Math.max(enrolled, 0));
  message += `${f.month || 'n/a'}: ${bar} ${enrolled} enrolled | $${rev.toLocaleString()}\n`;
}

const latest = last6[last6.length - 1]?.fields || {};
const prev = last6[last6.length - 2]?.fields || {};
const currentRevenue = Number(latest.monthly_revenue || 0);
const prevRevenue = Number(prev.monthly_revenue || 0);
if (prevRevenue > 0) {
  const deltaPct = ((currentRevenue - prevRevenue) / prevRevenue) * 100;
  const emoji = deltaPct >= 0 ? '📈' : '📉';
  message += `\n*Revenue:* $${currentRevenue.toLocaleString()}/mo`;
  message += `\n${emoji} ${deltaPct.toFixed(1)}% vs ${prev.month || 'prior month'}`;
}

if (last6.length >= 4) {
  const prior3 = last6.slice(-4, -1).map(r => r.fields || {});
  const avgEnroll = prior3.reduce((n, r) => n + Number(r.total_enrolled || 0), 0) / 3;
  const avgRev = prior3.reduce((n, r) => n + Number(r.monthly_revenue || 0), 0) / 3;
  const curEnroll = Number(latest.total_enrolled || 0);
  const anomalies = [];
  if (avgEnroll > 0 && curEnroll < avgEnroll * 0.9) anomalies.push('enrollment drop >10% vs prior 3-month average');
  if (avgRev > 0 && currentRevenue < avgRev * 0.9) anomalies.push('revenue drop >10% vs prior 3-month average');
  if (anomalies.length) {
    message += `\n\n⚠ *Anomaly:* ${anomalies.join('; ')}`;
  }
}

const highRisk = openWaitlist.filter(w => Number(w.fields?.retention_risk_score || 0) >= 70).length;
const mediumRisk = openWaitlist.filter(w => {
  const score = Number(w.fields?.retention_risk_score || 0);
  return score >= 40 && score < 70;
}).length;
message += `\n\n*Churn Proxy:* high-risk leads ${highRisk}, medium-risk leads ${mediumRisk}`;

const roomCapacity = roomRatios.reduce((sum, row) => sum + Number(row.fields?.max_children || 0), 0);
const assumedCapacity = Number(assumptions.licensed_capacity || 0);
const capacity = roomCapacity > 0 ? roomCapacity : assumedCapacity;
const utilization = capacity > 0 ? Math.round((active.length / capacity) * 100) : null;
if (utilization === null) {
  message += `\n*Capacity utilization:* unavailable (set FORECAST_LICENSED_CAPACITY or Room Ratios.max_children)`;
} else {
  message += `\n*Capacity utilization:* ${utilization}% (${active.length}/${Math.round(capacity)})`;
}

let avgRevenuePerChild = Number(assumptions.avg_revenue_per_child || 0);
if (avgRevenuePerChild <= 0) {
  const revPerChildSeries = last6
    .map(item => item.fields || {})
    .map(f => {
      const enrolled = Number(f.total_enrolled || 0);
      const rev = Number(f.monthly_revenue || 0);
      return enrolled > 0 && rev > 0 ? rev / enrolled : 0;
    })
    .filter(v => v > 0);
  if (revPerChildSeries.length > 0) {
    avgRevenuePerChild = revPerChildSeries.reduce((n, v) => n + v, 0) / revPerChildSeries.length;
  } else if (active.length > 0 && currentRevenue > 0) {
    avgRevenuePerChild = currentRevenue / active.length;
  }
}

const candidateBreakevenCost = [
  Number(assumptions.operating_cost || 0),
  Number(latest.breakeven_monthly_cost || 0),
  Number(latest.operating_cost || 0),
  Number(latest.monthly_cost || 0),
  Number(latest.fixed_costs || 0),
].find(v => v > 0) || 0;

let breakevenChildren = null;
if (candidateBreakevenCost > 0 && avgRevenuePerChild > 0) {
  breakevenChildren = Math.ceil(candidateBreakevenCost / avgRevenuePerChild);
  const gap = breakevenChildren - active.length;
  if (gap > 0) {
    message += `\n*Breakeven:* needs ~${breakevenChildren} children (gap: ${gap})`;
  } else {
    message += `\n*Breakeven:* above threshold by ${Math.abs(gap)} children`;
  }
} else {
  message += `\n*Breakeven:* unavailable (set FORECAST_OPERATING_COST/BREAKEVEN_MONTHLY_COST and AVG_MONTHLY_REVENUE_PER_CHILD)`;
}

return [{json: {message, active_count: active.length, waitlist_open: openWaitlist.length, utilization, capacity: capacity > 0 ? Math.round(capacity) : null, high_risk_leads: highRisk, medium_risk_leads: mediumRisk, avg_revenue_per_child: avgRevenuePerChild > 0 ? Number(avgRevenuePerChild.toFixed(2)) : null, breakeven_children: breakevenChildren, operating_cost: candidateBreakevenCost || null}}];
